using HRM.Models;using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace HRM.Api.Data.EntityConfigurations;
public sealed class RecruitmentApplicantsMapping:IEntityTypeConfiguration<RecruitmentApplicant>,IEntityTypeConfiguration<RecruitmentApplication>{public void Configure(EntityTypeBuilder<RecruitmentApplicant>b){b.ToTable("RM_RecruitmentApplicants");b.HasKey(x=>x.Id);b.Property(x=>x.Reference).HasMaxLength(80).IsRequired();b.Property(x=>x.EfaasIdNumber).HasMaxLength(80).IsRequired();b.Property(x=>x.FullName).HasMaxLength(250).IsRequired();b.Property(x=>x.Email).HasMaxLength(320).IsRequired();b.Property(x=>x.Mobile).HasMaxLength(40);b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.Reference).IsUnique();b.HasIndex(x=>x.EfaasIdNumber).IsUnique();b.HasIndex(x=>x.Email).IsUnique();}public void Configure(EntityTypeBuilder<RecruitmentApplication>b){b.ToTable("RM_RecruitmentApplications");b.HasKey(x=>x.Id);b.Property(x=>x.Reference).HasMaxLength(80).IsRequired();b.Property(x=>x.Status).HasMaxLength(40).IsRequired();b.Property(x=>x.ProfileSnapshotJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.Reference).IsUnique();b.HasIndex(x=>new{x.RecruitmentApplicantId,x.RecruitmentVacancyId}).IsUnique();b.HasIndex(x=>new{x.OrganisationId,x.Status,x.SubmittedAtUtc});b.HasOne<RecruitmentApplicant>().WithMany().HasForeignKey(x=>x.RecruitmentApplicantId).OnDelete(DeleteBehavior.Restrict);b.HasOne<RecruitmentVacancy>().WithMany().HasForeignKey(x=>x.RecruitmentVacancyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}}
